(()=>{"use strict";const D=document,W=window,V=new URL("viewer/",D.baseURI);let host,frame,closeButton,priorFocus,priorOverflow;const name=/^[a-z0-9_.-]{1,100}$/i;function urlFor(o){o=o||{};let u=new URL(V);if(o.repo){if(!name.test(o.repo))throw Error("Repository non valido");u.searchParams.set("repo",o.repo)}if(o.app===true){if(o.repo!=="NULLGOD-MUSIC")throw Error("Modalità app non supportata");u.searchParams.set("app","1")}return u.href}function ensure(){if(host)return;host=D.createElement("section");host.id="obscura-webplayer-host";host.setAttribute("role","dialog");host.setAttribute("aria-modal","true");host.setAttribute("aria-label","WebPlayer OBSCURA/07");host.hidden=true;host.style.cssText="position:fixed;inset:0;z-index:2147482000;background:#08090e;overflow:hidden";frame=D.createElement("iframe");frame.title="WebPlayer OBSCURA/07";frame.setAttribute("allow","autoplay;fullscreen");frame.setAttribute("allowfullscreen","");frame.style.cssText="width:100%;height:100%;border:0;display:block;background:#08090e";closeButton=D.createElement("button");closeButton.type="button";closeButton.textContent="×";closeButton.setAttribute("aria-label","Chiudi WebPlayer");closeButton.title="Chiudi WebPlayer";closeButton.style.cssText="position:absolute;z-index:2;top:env(safe-area-inset-top,0px);right:8px;width:30px;height:30px;border:1px solid #4a4359;border-radius:6px;background:#16131bdc;color:#ddd;font:22px/1 Arial;cursor:pointer";closeButton.addEventListener("click",close);host.append(frame,closeButton);D.body.append(host)}function open(o){ensure();const target=urlFor(o);priorFocus=D.activeElement;priorOverflow=D.documentElement.style.overflow;host.hidden=false;D.documentElement.style.overflow="hidden";if(frame.src!==target)frame.src=target;closeButton.focus();return true}function close(){if(!host||host.hidden)return;host.hidden=true;D.documentElement.style.overflow=priorOverflow||"";priorFocus?.focus?.();}function destroy(){if(!host)return;close();frame.src="about:blank";host.remove();host=frame=closeButton=null}D.addEventListener("keydown",e=>{if(e.key==="Escape"&&host&&!host.hidden&&D.activeElement!==frame){e.preventDefault();close()}});D.addEventListener("click",e=>{const link=e.target.closest?.("a[data-obscura-webplayer]");if(!link||e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey||e.altKey||e.shiftKey)return;e.preventDefault();open({repo:link.dataset.repo||"",app:link.dataset.app==="1"})});W.ObscuraWebPlayer=Object.freeze({open,close,destroy,urlFor});})();
